-- Module 2 geoBoundaries MYS ADM1 East Malaysia boundary seed.
--
-- Source: geoBoundaries MYS ADM1, created by geoBoundaries / William & Mary
-- geoLab and contributors, licensed under CC BY 4.0.
-- Project: https://www.geoboundaries.org/
-- Licence: https://creativecommons.org/licenses/by/4.0/
-- Approved source SHA-256:
-- de8b44337315de60019951d76744765ebdd5efc9c5823e0933b4dc15a0ed20d4
--
-- Only the full-resolution Sabah (MY-12), Sarawak (MY-13), and Labuan
-- (MY-15) MultiPolygon geometries are embedded. CRS84 longitude/X and
-- latitude/Y coordinates are assigned SRID 4326 without axis swapping,
-- simplification, buffering, inferred geometry, or automatic repair.

-- Fail closed unless the reviewed geography and company-assessment foundation
-- is intact and both owner-maintained boundary tables are still empty.
do $module2_seed_preconditions$
declare
  v_postgis_schema text;
  v_check record;
  v_has_privilege boolean;
begin
  if exists (
    select 1
    from (values ('anon'), ('authenticated'), ('service_role'))
      as required_role(role_name)
    where not exists (
      select 1
      from pg_catalog.pg_roles as role_entry
      where role_entry.rolname = required_role.role_name
    )
  ) then
    raise exception
      'Module 2 boundary seed requires anon, authenticated, and service_role roles';
  end if;

  if pg_catalog.to_regclass('public.profiles') is null
    or pg_catalog.to_regclass('public.fuel_companies') is null
    or pg_catalog.to_regclass('public.station_assessments') is null
    or pg_catalog.to_regclass(
      'public.east_malaysia_boundary_datasets'
    ) is null
    or pg_catalog.to_regclass(
      'public.east_malaysia_territory_boundaries'
    ) is null then
    raise exception
      'Module 2 boundary seed requires the deployed geography foundation tables';
  end if;

  select namespace.nspname
  into v_postgis_schema
  from pg_catalog.pg_extension as extension_entry
  join pg_catalog.pg_namespace as namespace
    on namespace.oid = extension_entry.extnamespace
  where extension_entry.extname = 'postgis';

  if v_postgis_schema is distinct from 'gis' then
    raise exception
      'Module 2 boundary seed requires PostGIS in schema gis';
  end if;

  if pg_catalog.to_regprocedure(
    'public.validate_east_malaysia_site(double precision,double precision,smallint)'
  ) is null
    or pg_catalog.to_regprocedure(
      'public.current_assessment_company_id()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.current_user_is_company_admin()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.set_station_assessment_ownership()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.prevent_station_assessment_ownership_change()'
    ) is null then
    raise exception
      'Module 2 boundary seed requires geography and company ownership functions';
  end if;

  if exists (
    select 1
    from (
      values
        ('east_malaysia_boundary_datasets', 'id'),
        ('east_malaysia_boundary_datasets', 'source_provider'),
        ('east_malaysia_boundary_datasets', 'source_reference'),
        ('east_malaysia_boundary_datasets', 'source_version'),
        ('east_malaysia_boundary_datasets', 'source_release_date'),
        ('east_malaysia_boundary_datasets', 'licence'),
        ('east_malaysia_boundary_datasets', 'attribution'),
        ('east_malaysia_boundary_datasets', 'is_active'),
        ('east_malaysia_boundary_datasets', 'created_at'),
        ('east_malaysia_boundary_datasets', 'updated_at'),
        ('east_malaysia_territory_boundaries', 'id'),
        ('east_malaysia_territory_boundaries', 'dataset_id'),
        ('east_malaysia_territory_boundaries', 'territory'),
        ('east_malaysia_territory_boundaries', 'boundary'),
        ('east_malaysia_territory_boundaries', 'created_at'),
        ('east_malaysia_territory_boundaries', 'updated_at'),
        ('profiles', 'user_id'),
        ('profiles', 'company_id'),
        ('profiles', 'role'),
        ('station_assessments', 'id'),
        ('station_assessments', 'company_id'),
        ('station_assessments', 'site_location'),
        ('station_assessments', 'analysis_radius_km'),
        ('station_assessments', 'geographic_validation_status'),
        ('station_assessments', 'confirmed_territory'),
        ('station_assessments', 'boundary_dataset_id'),
        ('station_assessments', 'geographically_validated_at')
    ) as required_column(table_name, column_name)
    where not exists (
      select 1
      from information_schema.columns as existing_column
      where existing_column.table_schema = 'public'
        and existing_column.table_name = required_column.table_name
        and existing_column.column_name = required_column.column_name
    )
  ) then
    raise exception
      'Module 2 boundary seed required columns are missing';
  end if;

  if exists (
    select 1
    from (
      values
        ('east_malaysia_boundary_dataset_provider_not_blank'),
        ('east_malaysia_boundary_dataset_reference_not_blank'),
        ('east_malaysia_boundary_dataset_version_not_blank'),
        ('east_malaysia_boundary_dataset_licence_not_blank'),
        ('east_malaysia_boundary_dataset_attribution_not_blank'),
        ('east_malaysia_boundary_dataset_source_unique'),
        ('east_malaysia_territory_boundary_dataset_fkey'),
        ('east_malaysia_territory_boundary_value_check'),
        ('east_malaysia_territory_boundary_dataset_unique'),
        ('east_malaysia_territory_boundary_not_empty'),
        ('east_malaysia_territory_boundary_valid'),
        ('east_malaysia_territory_boundary_two_dimensional'),
        ('east_malaysia_territory_boundary_srid'),
        ('east_malaysia_territory_boundary_multipolygon')
    ) as required_constraint(constraint_name)
    where not exists (
      select 1
      from pg_catalog.pg_constraint as constraint_entry
      where constraint_entry.conname = required_constraint.constraint_name
        and constraint_entry.conrelid in (
          'public.east_malaysia_boundary_datasets'::regclass,
          'public.east_malaysia_territory_boundaries'::regclass
        )
    )
  ) then
    raise exception
      'Module 2 boundary seed geography constraints are incomplete';
  end if;

  if exists (
    select 1
    from (
      values
        ('east_malaysia_boundary_datasets_one_active_idx'),
        ('east_malaysia_territory_boundaries_boundary_gist_idx'),
        ('station_assessments_site_location_gist_idx')
    ) as required_index(index_name)
    where pg_catalog.to_regclass(
      pg_catalog.format('public.%I', required_index.index_name)
    ) is null
  ) then
    raise exception
      'Module 2 boundary seed geography indexes are incomplete';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.pg_trigger as trigger_entry
    where not trigger_entry.tgisinternal
      and (
        (
          trigger_entry.tgrelid =
            'public.east_malaysia_boundary_datasets'::regclass
          and trigger_entry.tgname =
            'update_east_malaysia_boundary_datasets_updated_at'
        )
        or (
          trigger_entry.tgrelid =
            'public.east_malaysia_territory_boundaries'::regclass
          and trigger_entry.tgname =
            'update_east_malaysia_territory_boundaries_updated_at'
        )
      )
  ) <> 2 then
    raise exception
      'Module 2 boundary seed boundary timestamp triggers are incomplete';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.pg_trigger as trigger_entry
    where trigger_entry.tgrelid = 'public.station_assessments'::regclass
      and not trigger_entry.tgisinternal
      and trigger_entry.tgname in (
        'set_station_assessment_ownership',
        'prevent_station_assessment_ownership_change',
        'update_station_assessments_updated_at'
      )
  ) <> 3 then
    raise exception
      'Module 2 boundary seed company assessment triggers are incomplete';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.pg_policies as policy_entry
    where policy_entry.schemaname = 'public'
      and policy_entry.tablename = 'station_assessments'
  ) <> 4
    or exists (
      select 1
      from (
        values
          ('Company members can view company assessments'),
          ('Company members can create own company assessments'),
          ('Creators and company admins can update company assessments'),
          ('Creators and company admins can delete company assessments')
      ) as required_policy(policy_name)
      where not exists (
        select 1
        from pg_catalog.pg_policies as existing_policy
        where existing_policy.schemaname = 'public'
          and existing_policy.tablename = 'station_assessments'
          and existing_policy.policyname = required_policy.policy_name
      )
    ) then
    raise exception
      'Module 2 boundary seed company assessment policy matrix differs';
  end if;

  if exists (
    select profile.user_id
    from public.profiles as profile
    group by profile.user_id
    having pg_catalog.count(*) > 1
  )
    or exists (
      select 1
      from public.station_assessments as assessment
      where assessment.company_id is null
    ) then
    raise exception
      'Module 2 boundary seed requires authoritative unique company ownership';
  end if;

  if exists (
    select 1
    from public.east_malaysia_boundary_datasets as dataset
    where dataset.is_active
  ) then
    raise exception
      'Module 2 boundary seed refuses to replace an active boundary dataset';
  end if;

  if exists (
    select 1 from public.east_malaysia_boundary_datasets
  )
    or exists (
      select 1 from public.east_malaysia_territory_boundaries
    ) then
    raise exception
      'Module 2 boundary seed requires empty boundary tables';
  end if;

  if not (
    select pg_catalog.bool_and(relation.relrowsecurity)
    from pg_catalog.pg_class as relation
    where relation.oid in (
      'public.east_malaysia_boundary_datasets'::regclass,
      'public.east_malaysia_territory_boundaries'::regclass
    )
  )
    or exists (
      select 1
      from pg_catalog.pg_policy as policy_entry
      where policy_entry.polrelid in (
        'public.east_malaysia_boundary_datasets'::regclass,
        'public.east_malaysia_territory_boundaries'::regclass
      )
    ) then
    raise exception
      'Module 2 boundary seed requires RLS with zero boundary API policies';
  end if;

  for v_check in
    select
      checked_role.role_name,
      boundary_table.table_name,
      checked_privilege.privilege_name
    from (values ('PUBLIC'), ('anon'), ('authenticated'), ('service_role'))
      as checked_role(role_name)
    cross join (
      values
        ('public.east_malaysia_boundary_datasets'),
        ('public.east_malaysia_territory_boundaries')
    ) as boundary_table(table_name)
    cross join (values ('SELECT'), ('INSERT'), ('UPDATE'), ('DELETE'))
      as checked_privilege(privilege_name)
  loop
    if v_check.role_name = 'PUBLIC' then
      select exists (
        select 1
        from pg_catalog.pg_class as relation
        cross join lateral pg_catalog.aclexplode(
          coalesce(
            relation.relacl,
            pg_catalog.acldefault('r', relation.relowner)
          )
        ) as table_acl
        where relation.oid = pg_catalog.to_regclass(v_check.table_name)
          and table_acl.grantee = 0
          and table_acl.privilege_type = v_check.privilege_name
      )
      into v_has_privilege;
    else
      v_has_privilege := pg_catalog.has_table_privilege(
        v_check.role_name,
        v_check.table_name,
        v_check.privilege_name
      );
    end if;

    if v_has_privilege then
      raise exception
        'Module 2 boundary seed requires denied % on % for role %',
        v_check.privilege_name,
        v_check.table_name,
        v_check.role_name;
    end if;
  end loop;

  if exists (
    select 1
    from pg_catalog.pg_proc as procedure_entry
    cross join lateral pg_catalog.aclexplode(
      coalesce(
        procedure_entry.proacl,
        pg_catalog.acldefault('f', procedure_entry.proowner)
      )
    ) as function_acl
    where procedure_entry.oid =
      'public.validate_east_malaysia_site(double precision,double precision,smallint)'::regprocedure
      and function_acl.grantee = 0
      and function_acl.privilege_type = 'EXECUTE'
  )
    or pg_catalog.has_function_privilege(
      'anon',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    )
    or not pg_catalog.has_function_privilege(
      'authenticated',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    )
    or not pg_catalog.has_function_privilege(
      'service_role',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    ) then
    raise exception
      'Module 2 boundary seed validator ACL differs from the geography foundation';
  end if;
end;
$module2_seed_preconditions$;

-- Snapshot complete assessment rows. The seed is reference-data-only and must
-- not alter any assessment ID, ownership, scoring, geography, or timestamp.
create temporary table module2_boundary_seed_assessment_snapshot
on commit drop
as
select
  assessment.id,
  pg_catalog.to_jsonb(assessment) as row_data
from public.station_assessments as assessment;

create temporary table module2_geoboundaries_mys_adm1_stage (
  territory text primary key,
  shape_name text not null,
  shape_iso text not null,
  shape_id text not null unique,
  boundary gis.geometry(MultiPolygon, 4326) not null
)
on commit drop;

