    select 1
    from pg_temp.module2_geoboundaries_mys_adm1_stage as staged
    where staged.boundary is null
      or gis.st_isempty(staged.boundary)
      or not gis.st_isvalid(staged.boundary)
      or gis.st_ndims(staged.boundary) <> 2
      or gis.st_srid(staged.boundary) <> 4326
      or gis.st_geometrytype(staged.boundary) <> 'ST_MultiPolygon'
  ) then
    raise exception
      'Module 2 boundary seed source geometry is empty, invalid, or structurally unexpected';
  end if;

  if exists (
    select 1
    from pg_temp.module2_geoboundaries_mys_adm1_stage as first_boundary
    join pg_temp.module2_geoboundaries_mys_adm1_stage as second_boundary
      on first_boundary.territory < second_boundary.territory
    where gis.st_relate(
      first_boundary.boundary,
      second_boundary.boundary,
      '2********'
    )
  ) then
    raise exception
      'Module 2 boundary seed territories overlap by area';
  end if;
end;
$module2_seed_validate_stage$;

-- Deterministic UUID derived from the approved SHA-256 prefix with UUIDv5
-- version/variant bits applied: de8b44337315de60019951d76744765e.
insert into public.east_malaysia_boundary_datasets (
  id,
  source_provider,
  source_reference,
  source_version,
  source_release_date,
  licence,
  attribution,
  is_active
)
values (
  'de8b4433-7315-5e60-8195-1d76744765eb',
  'geoBoundaries MYS ADM1',
  'https://www.geoboundaries.org/',
  'MYS ADM1 source SHA-256 de8b44337315de60019951d76744765ebdd5efc9c5823e0933b4dc15a0ed20d4',
  null,
  'Creative Commons Attribution 4.0 International (CC BY 4.0); https://creativecommons.org/licenses/by/4.0/',
  'geoBoundaries / William & Mary geoLab and contributors. Only Sabah, Sarawak, and Labuan were extracted and converted from OGC CRS84 to PostGIS SRID 4326 without axis swapping, simplification, buffering, manual editing, or repair. No endorsement or official Malaysian government status is implied; the source provides no warranty.',
  false
);

insert into public.east_malaysia_territory_boundaries (
  id,
  dataset_id,
  territory,
  boundary
)
select
  case staged.territory
    when 'sabah' then 'de8b4433-7315-5e60-8195-1d7674476501'::uuid
    when 'sarawak' then 'de8b4433-7315-5e60-8195-1d7674476502'::uuid
    when 'labuan' then 'de8b4433-7315-5e60-8195-1d7674476503'::uuid
  end,
  'de8b4433-7315-5e60-8195-1d76744765eb'::uuid,
  staged.territory,
  staged.boundary
from pg_temp.module2_geoboundaries_mys_adm1_stage as staged
order by staged.territory;

do $module2_seed_pre_activation$
begin
  if (
    select pg_catalog.count(*)
    from public.east_malaysia_territory_boundaries as boundary_entry
    where boundary_entry.dataset_id =
      'de8b4433-7315-5e60-8195-1d76744765eb'
  ) <> 3
    or (
      select pg_catalog.count(distinct boundary_entry.territory)
      from public.east_malaysia_territory_boundaries as boundary_entry
      where boundary_entry.dataset_id =
        'de8b4433-7315-5e60-8195-1d76744765eb'
    ) <> 3
    or exists (
      select 1
      from public.east_malaysia_territory_boundaries as boundary_entry
      where boundary_entry.dataset_id =
        'de8b4433-7315-5e60-8195-1d76744765eb'
        and (
          gis.st_isempty(boundary_entry.boundary)
          or not gis.st_isvalid(boundary_entry.boundary)
          or gis.st_ndims(boundary_entry.boundary) <> 2
          or gis.st_srid(boundary_entry.boundary) <> 4326
          or gis.st_geometrytype(boundary_entry.boundary) <>
            'ST_MultiPolygon'
        )
    ) then
    raise exception
      'Module 2 boundary seed persisted dataset is incomplete or invalid';
  end if;
end;
$module2_seed_pre_activation$;

-- Activation is intentionally the final data mutation. The validator observes
-- no dataset until all three exact geometries have passed every check.
update public.east_malaysia_boundary_datasets
set is_active = true
where id = 'de8b4433-7315-5e60-8195-1d76744765eb'
  and not is_active;

do $module2_seed_postconditions$
declare
  v_check record;
  v_has_privilege boolean;
begin
  if (
    select pg_catalog.count(*)
    from public.east_malaysia_boundary_datasets as dataset
    where dataset.id = 'de8b4433-7315-5e60-8195-1d76744765eb'
      and dataset.is_active
  ) <> 1
    or (
      select pg_catalog.count(*)
      from public.east_malaysia_boundary_datasets as dataset
      where dataset.is_active
    ) <> 1 then
    raise exception
      'Module 2 boundary seed did not activate exactly one dataset';
  end if;

  if (
    select pg_catalog.count(*)
    from public.east_malaysia_territory_boundaries as boundary_entry
    where boundary_entry.dataset_id =
      'de8b4433-7315-5e60-8195-1d76744765eb'
  ) <> 3
    or exists (
      select 1
      from public.east_malaysia_territory_boundaries as first_boundary
      join public.east_malaysia_territory_boundaries as second_boundary
        on first_boundary.territory < second_boundary.territory
        and first_boundary.dataset_id = second_boundary.dataset_id
      where first_boundary.dataset_id =
        'de8b4433-7315-5e60-8195-1d76744765eb'
        and gis.st_relate(
          first_boundary.boundary,
          second_boundary.boundary,
          '2********'
        )
    ) then
    raise exception
      'Module 2 boundary seed active territory set is incomplete or overlapping';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_temp.module2_boundary_seed_assessment_snapshot
  ) <> (
    select pg_catalog.count(*)
    from public.station_assessments
  )
    or exists (
      select 1
      from pg_temp.module2_boundary_seed_assessment_snapshot as original
      full join public.station_assessments as assessment
        on assessment.id = original.id
      where original.id is null
        or assessment.id is null
        or pg_catalog.to_jsonb(assessment) is distinct from original.row_data
    ) then
    raise exception
      'Module 2 boundary seed changed an existing assessment';
  end if;

  if not (
    select pg_catalog.bool_and(relation.relrowsecurity)
    from pg_catalog.pg_class as relation
    where relation.oid in (
      'public.east_malaysia_boundary_datasets'::regclass,
      'public.east_malaysia_territory_boundaries'::regclass
    )
  )
    or exists (
      select 1
      from pg_catalog.pg_policy as policy_entry
      where policy_entry.polrelid in (
        'public.east_malaysia_boundary_datasets'::regclass,
        'public.east_malaysia_territory_boundaries'::regclass
      )
    ) then
    raise exception
      'Module 2 boundary seed changed boundary RLS or policy state';
  end if;

  for v_check in
    select
      checked_role.role_name,
      boundary_table.table_name,
      checked_privilege.privilege_name
    from (values ('PUBLIC'), ('anon'), ('authenticated'), ('service_role'))
      as checked_role(role_name)
    cross join (
      values
        ('public.east_malaysia_boundary_datasets'),
        ('public.east_malaysia_territory_boundaries')
    ) as boundary_table(table_name)
    cross join (values ('SELECT'), ('INSERT'), ('UPDATE'), ('DELETE'))
      as checked_privilege(privilege_name)
  loop
    if v_check.role_name = 'PUBLIC' then
      select exists (
        select 1
        from pg_catalog.pg_class as relation
        cross join lateral pg_catalog.aclexplode(
          coalesce(
            relation.relacl,
            pg_catalog.acldefault('r', relation.relowner)
          )
        ) as table_acl
        where relation.oid = pg_catalog.to_regclass(v_check.table_name)
          and table_acl.grantee = 0
          and table_acl.privilege_type = v_check.privilege_name
      )
      into v_has_privilege;
    else
      v_has_privilege := pg_catalog.has_table_privilege(
        v_check.role_name,
        v_check.table_name,
        v_check.privilege_name
      );
    end if;

    if v_has_privilege then
      raise exception
        'Module 2 boundary seed changed % on % for role %',
        v_check.privilege_name,
        v_check.table_name,
        v_check.role_name;
    end if;
  end loop;

  if (
    select pg_catalog.count(*)
    from pg_catalog.pg_policies as policy_entry
    where policy_entry.schemaname = 'public'
      and policy_entry.tablename = 'station_assessments'
  ) <> 4
    or (
      select pg_catalog.count(*)
      from pg_catalog.pg_trigger as trigger_entry
      where trigger_entry.tgrelid = 'public.station_assessments'::regclass
        and not trigger_entry.tgisinternal
        and trigger_entry.tgname in (
          'set_station_assessment_ownership',
          'prevent_station_assessment_ownership_change',
          'update_station_assessments_updated_at'
        )
    ) <> 3
    or (
      select pg_catalog.count(*)
      from pg_catalog.pg_trigger as trigger_entry
      where not trigger_entry.tgisinternal
        and (
          (
            trigger_entry.tgrelid =
              'public.east_malaysia_boundary_datasets'::regclass
            and trigger_entry.tgname =
              'update_east_malaysia_boundary_datasets_updated_at'
          )
          or (
            trigger_entry.tgrelid =
              'public.east_malaysia_territory_boundaries'::regclass
            and trigger_entry.tgname =
              'update_east_malaysia_territory_boundaries_updated_at'
          )
        )
    ) <> 2 then
    raise exception
      'Module 2 boundary seed changed company assessment authorization objects';
  end if;

  if pg_catalog.to_regprocedure(
    'public.validate_east_malaysia_site(double precision,double precision,smallint)'
  ) is null
    or pg_catalog.to_regprocedure(
      'public.current_assessment_company_id()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.current_user_is_company_admin()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.set_station_assessment_ownership()'
    ) is null
    or pg_catalog.to_regprocedure(
      'public.prevent_station_assessment_ownership_change()'
    ) is null
    or exists (
      select 1
      from (
        values
          ('east_malaysia_boundary_datasets_one_active_idx'),
          ('east_malaysia_territory_boundaries_boundary_gist_idx'),
          ('station_assessments_site_location_gist_idx'),
          ('station_assessments_user_id_idx'),
          ('station_assessments_company_id_idx'),
          ('station_assessments_company_created_at_idx')
      ) as required_index(index_name)
      where pg_catalog.to_regclass(
        pg_catalog.format('public.%I', required_index.index_name)
      ) is null
    ) then
    raise exception
      'Module 2 boundary seed changed required functions or indexes';
  end if;

  if exists (
    select 1
    from pg_catalog.pg_proc as procedure_entry
    cross join lateral pg_catalog.aclexplode(
      coalesce(
        procedure_entry.proacl,
        pg_catalog.acldefault('f', procedure_entry.proowner)
      )
    ) as function_acl
    where procedure_entry.oid =
      'public.validate_east_malaysia_site(double precision,double precision,smallint)'::regprocedure
      and function_acl.grantee = 0
      and function_acl.privilege_type = 'EXECUTE'
  )
    or pg_catalog.has_function_privilege(
      'anon',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    )
    or not pg_catalog.has_function_privilege(
      'authenticated',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    )
    or not pg_catalog.has_function_privilege(
      'service_role',
      'public.validate_east_malaysia_site(double precision,double precision,smallint)',
      'EXECUTE'
    ) then
    raise exception
      'Module 2 boundary seed changed validator privileges';
  end if;
end;
$module2_seed_postconditions$;
